-- Starter templates got HTML designs (Twenty CRM look, Reply / website /
-- quick-reply buttons). Existing workspaces were seeded with the old plain
-- versions: replace a starter template ONLY where its name, subject and body
-- are still exactly the old default, so anything a user edited is untouched.
-- Runs as the migration owner (RLS owner_bypass, migration 0046).
UPDATE templates SET subject = $tpl$Quick question, {first_name|there}$tpl$, body_html = $tpl$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7f7f8;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #ebebeb;border-radius:10px;"><tr><td style="padding:28px 32px;"><div style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 18px;font-size:12px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;color:#3e63dd;">{sender_company|Hello}</div><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Hi {first_name|there},</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">I came across {business_name|your company} and thought there might be a fit. We help teams like yours run outbound without the manual grind.</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Open to a quick 15-minute call this week?</p><div style="margin:6px 0 4px;"><a href="mailto:{sender_email}?subject=Re%3A%20Quick%20question" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#3e63dd;color:#ffffff;text-decoration:none;font-size:14px;font-weight:600;line-height:20px;padding:10px 18px;border-radius:6px;margin:0 8px 8px 0;">Reply to {sender_name}</a><a href="{sender_website}" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#ffffff;color:#333333;text-decoration:none;font-size:14px;font-weight:600;line-height:20px;padding:9px 17px;border:1px solid #d6d6d6;border-radius:6px;margin:0 8px 8px 0;">Visit our website</a></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;border-top:1px solid #ebebeb;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding-top:16px;font-size:14px;line-height:1.5;color:#333333;"><strong style="font-weight:600;">{sender_name}</strong><br><span style="color:#818181;">{sender_company|}</span></td></tr></table></td></tr></table></td></tr></table>$tpl$, updated_at = now()
WHERE name = $tpl$Cold intro$tpl$ AND subject = $tpl$Quick question, {first_name|there}$tpl$ AND body_html = $tpl$<p>Hi {first_name|there},</p><p>I came across {business_name|your company} and thought there might be a fit. We help teams like yours run outbound without the manual grind.</p><p>Open to a quick 15-min call this week?</p><p>Best,<br>{sender_name}</p>$tpl$;--> statement-breakpoint

UPDATE templates SET subject = $tpl$Re: Quick question, {first_name|there}$tpl$, body_html = $tpl$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7f7f8;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #ebebeb;border-radius:10px;"><tr><td style="padding:28px 32px;"><div style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 18px;font-size:12px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;color:#3e63dd;">{sender_company|Hello}</div><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Hi {first_name|there},</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Floating this back to the top of your inbox. Worth a short chat? One tap is enough:</p><div style="margin:6px 0 4px;"><a href="mailto:{sender_email}?subject=Re%3A%20Quick%20question&amp;body=Yes%2C%20let%E2%80%99s%20talk." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Yes, let’s talk</a><a href="mailto:{sender_email}?subject=Re%3A%20Quick%20question&amp;body=Maybe%20later." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Maybe later</a><a href="mailto:{sender_email}?subject=Re%3A%20Quick%20question&amp;body=Not%20for%20us%2C%20thanks." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Not for us</a></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;border-top:1px solid #ebebeb;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding-top:16px;font-size:14px;line-height:1.5;color:#333333;"><strong style="font-weight:600;">{sender_name}</strong><br><span style="color:#818181;">{sender_company|}</span></td></tr></table></td></tr></table></td></tr></table>$tpl$, updated_at = now()
WHERE name = $tpl$Follow-up #1$tpl$ AND subject = $tpl$Re: Quick question, {first_name|there}$tpl$ AND body_html = $tpl$<p>Hi {first_name|there},</p><p>Floating this back to the top of your inbox. Worth a short chat?</p><p>Best,<br>{sender_name}</p>$tpl$;--> statement-breakpoint

UPDATE templates SET subject = $tpl$Should I close the loop?$tpl$, body_html = $tpl$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7f7f8;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #ebebeb;border-radius:10px;"><tr><td style="padding:28px 32px;"><div style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 18px;font-size:12px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;color:#3e63dd;">{sender_company|Hello}</div><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Hi {first_name|there},</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Haven’t heard back, so I’ll assume the timing isn’t right and stop following up.</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">If it’s still on your radar, let me know where things stand:</p><div style="margin:6px 0 4px;"><a href="mailto:{sender_email}?subject=Re%3A%20Should%20I%20close%20the%20loop%3F&amp;body=Still%20interested." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Still interested</a><a href="mailto:{sender_email}?subject=Re%3A%20Should%20I%20close%20the%20loop%3F&amp;body=Check%20back%20next%20quarter." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Check back next quarter</a><a href="mailto:{sender_email}?subject=Re%3A%20Should%20I%20close%20the%20loop%3F&amp;body=Please%20close%20it." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Please close it</a></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;border-top:1px solid #ebebeb;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding-top:16px;font-size:14px;line-height:1.5;color:#333333;"><strong style="font-weight:600;">{sender_name}</strong><br><span style="color:#818181;">{sender_company|}</span></td></tr></table></td></tr></table></td></tr></table>$tpl$, updated_at = now()
WHERE name = $tpl$Follow-up #2 (break-up)$tpl$ AND subject = $tpl$Should I close the loop?$tpl$ AND body_html = $tpl$<p>Hi {first_name|there},</p><p>Haven’t heard back, so I’ll assume the timing isn’t right. If that changes, just reply here.</p><p>All the best,<br>{sender_name}</p>$tpl$;--> statement-breakpoint

UPDATE templates SET subject = $tpl$15 minutes, {first_name|there}?$tpl$, body_html = $tpl$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7f7f8;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #ebebeb;border-radius:10px;"><tr><td style="padding:28px 32px;"><div style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 18px;font-size:12px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;color:#3e63dd;">{sender_company|Hello}</div><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Hi {first_name|there},</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Would a quick 15-minute call work this week? Happy to work around {business_name|your team}’s schedule. Pick what suits you:</p><div style="margin:6px 0 4px;"><a href="mailto:{sender_email}?subject=Re%3A%2015%20minutes&amp;body=Tuesday%20works%20for%20me." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Tuesday works</a><a href="mailto:{sender_email}?subject=Re%3A%2015%20minutes&amp;body=Thursday%20works%20for%20me." style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Thursday works</a><a href="mailto:{sender_email}?subject=Re%3A%2015%20minutes&amp;body=How%20about%20" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#edf0fd;color:#3e63dd;text-decoration:none;font-size:13px;font-weight:600;line-height:18px;padding:7px 14px;border-radius:999px;margin:0 6px 8px 0;">Suggest another time</a></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;border-top:1px solid #ebebeb;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding-top:16px;font-size:14px;line-height:1.5;color:#333333;"><strong style="font-weight:600;">{sender_name}</strong><br><span style="color:#818181;">{sender_company|}</span></td></tr></table></td></tr></table></td></tr></table>$tpl$, updated_at = now()
WHERE name = $tpl$Meeting request$tpl$ AND subject = $tpl$15 minutes, {first_name|there}?$tpl$ AND body_html = $tpl$<p>Hi {first_name|there},</p><p>Would Tuesday or Thursday work for a quick call? Happy to work around {business_name|your team}’s schedule.</p><p>Best,<br>{sender_name}</p>$tpl$;--> statement-breakpoint

UPDATE templates SET subject = $tpl$How teams like {business_name|yours} save hours weekly$tpl$, body_html = $tpl$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f7f7f8;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #ebebeb;border-radius:10px;"><tr><td style="padding:28px 32px;"><div style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 18px;font-size:12px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;color:#3e63dd;">{sender_company|Hello}</div><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Hi {first_name|there},</p><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">A team similar to {business_name|yours} rebuilt their outreach with us last quarter:</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 18px;background:#edf0fd;border-radius:8px;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:16px 18px;"><div style="font-size:24px;font-weight:700;line-height:1.2;color:#3e63dd;">50% less time on outreach</div><div style="margin-top:4px;font-size:13px;line-height:1.5;color:#333333;">Same pipeline, half the manual work, within the first month.</div></td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px;"><tr><td valign="top" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 10px 8px 0;font-size:15px;line-height:1.5;color:#3e63dd;">&#10003;</td><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 0 8px;font-size:15px;line-height:1.5;color:#333333;">Leads, sequences and replies in one place</td></tr><tr><td valign="top" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 10px 8px 0;font-size:15px;line-height:1.5;color:#3e63dd;">&#10003;</td><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 0 8px;font-size:15px;line-height:1.5;color:#333333;">AI drafts every follow-up; you approve</td></tr><tr><td valign="top" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 10px 8px 0;font-size:15px;line-height:1.5;color:#3e63dd;">&#10003;</td><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding:0 0 8px;font-size:15px;line-height:1.5;color:#333333;">Replies sorted automatically: interested, not now, out of office</td></tr></table><p style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;margin:0 0 14px;font-size:15px;line-height:1.6;color:#333333;">Happy to show you how it would look for your team.</p><div style="margin:6px 0 4px;"><a href="{sender_website}" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#3e63dd;color:#ffffff;text-decoration:none;font-size:14px;font-weight:600;line-height:20px;padding:10px 18px;border-radius:6px;margin:0 8px 8px 0;">See how it works</a><a href="mailto:{sender_email}?subject=Re%3A%20Saving%20hours%20weekly" style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;display:inline-block;background:#ffffff;color:#333333;text-decoration:none;font-size:14px;font-weight:600;line-height:20px;padding:9px 17px;border:1px solid #d6d6d6;border-radius:6px;margin:0 8px 8px 0;">Reply to {sender_name}</a></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;border-top:1px solid #ebebeb;"><tr><td style="font-family:Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;padding-top:16px;font-size:14px;line-height:1.5;color:#333333;"><strong style="font-weight:600;">{sender_name}</strong><br><span style="color:#818181;">{sender_company|}</span></td></tr></table></td></tr></table></td></tr></table>$tpl$, updated_at = now()
WHERE name = $tpl$Value / case study$tpl$ AND subject = $tpl$How teams like {business_name|yours} save hours weekly$tpl$ AND body_html = $tpl$<p>Hi {first_name|there},</p><p>A team similar to {business_name|yours} cut their outreach time in half last quarter. Happy to share how.</p><p>Interested?</p><p>Best,<br>{sender_name}</p>$tpl$;
